test("shared due per holder scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "terms-A", "20");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  await ui.setSetting(pg_uma, "grace-B", "5");
  await ui.setSetting(pg_uma, "pot", "100.00");
  await ui.setSetting(pg_uma, "fiscal-start-month", "4");
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt,photo");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "1");
  await ui.setSetting(pg_uma, "max-open", "1");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "3", "contact": "ben@x"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "20"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "contact": "ben@x"})).toBeNull();
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "12.50", "start": "2026-02-20", "end": "2026-04-30", "day": "15"}));
  expect(await ui.bulkHold(pg_uma, [p_cam, p_ben], {"from": "2026-03-15", "to": "2026-04-02"})).toBe(2);
  expect(await ui.inlineGrade(pg_uma, p_cam, "C")).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Cam")).toBe(true);
  expect(await ui.setApprover(pg_uma, p_cam, "vic")).toBe(true);
  await ui.setToday(pg_uma, "2026-05-15");
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.35", "date": "2026-02-10", "ref": "inv 7"}));
  expect(await ui.setSettingDated(pg_uma, "late-pct", "0.00", "2026-04-02", "5.00")).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("0.00");
